    @Test
    @DisplayName("Тест склонения дней, часов, минут по эталонным значениям")
    void convertValueAndChronoUnitToStringTest() {
        int size = 1000;
        
        StringBuilder daysCasesBuilder = new StringBuilder();
        StringBuilder hoursCasesBuilder = new StringBuilder();
        StringBuilder minutesCasesBuilder = new StringBuilder();
        
        for (int i = 0; i < size; i++) {
            daysCasesBuilder.append(ChronoUnitsCases.convertValueAndChronoUnitToString(ChronoUnit.DAYS, i))
                            .append(";");
            hoursCasesBuilder.append(ChronoUnitsCases.convertValueAndChronoUnitToString(ChronoUnit.HOURS, i))
                            .append(";");
            minutesCasesBuilder.append(ChronoUnitsCases.convertValueAndChronoUnitToString(ChronoUnit.MINUTES, i))
                            .append(";");
        }
        assertThat(daysCasesBuilder).hasToString(DAYS_CASES_GAUGE);
        assertThat(hoursCasesBuilder).hasToString(HOURS_CASES_GAUGE);
        assertThat(minutesCasesBuilder).hasToString(MINUTES_CASES_GAUGE);
    }
    
    @Test
    @DisplayName("Тест выброса исключения при указании неиспользуемой единицы измерения")
    void convertValueAndChronoUnitToStringTest_incorrectUnitException() {
        Throwable ex = catchThrowable(() -> ChronoUnitsCases.convertValueAndChronoUnitToString(ChronoUnit.DECADES, 5));
        assertThat(ex).isInstanceOf(IllegalArgumentException.class);
    }
